        }),
      )
    })
  })
})

import { trackEvent } from '@codebuff/common/analytics'
import { AnalyticsEvent } from '@codebuff/common/constants/analytics-events'
import {
  endsAgentStepParam,
  endToolTag,
  startToolTag,
  toolNameParam,
} from '@codebuff/common/tools/constants'

import type { Model } from '@codebuff/common/constants'
import type {
  PrintModeError,
  PrintModeText,
  PrintModeToolCall,
} from '@codebuff/common/types/print-mode'

const toolExtractionPattern = new RegExp(
  `${startToolTag}(.*?)${endToolTag}`,
  'gs',
)

const completionSuffix = `${JSON.stringify(endsAgentStepParam)}: true\n}${endToolTag}`

export async function* processStreamWithTags(
  stream: AsyncGenerator<string> | ReadableStream<string>,
  processors: Record<
    string,
    {
      onTagStart: (tagName: string, attributes: Record<string, string>) => void
      onTagEnd: (tagName: string, params: Record<string, any>) => void
    }
  >,
  onError: (tagName: string, errorMessage: string) => void,
  onResponseChunk: (
    chunk: PrintModeText | PrintModeToolCall | PrintModeError,
  ) => void,
  loggerOptions?: {
    userId?: string
    model?: Model
    agentName?: string
  },
): AsyncGenerator<string> {
  let streamCompleted = false
  let buffer = ''
  let autocompleted = false

  function extractToolCalls(): string[] {
    const matches: string[] = []
    let lastIndex = 0
    for (const match of buffer.matchAll(toolExtractionPattern)) {
      if (match.index > lastIndex) {
        onResponseChunk({
          type: 'text',
          text: buffer.slice(lastIndex, match.index),
        })
      }
      lastIndex = match.index + match[0].length
      matches.push(match[1])
    }

    buffer = buffer.slice(lastIndex)
    return matches
  }

  function processToolCallContents(contents: string): void {
    let parsedParams: any
    try {
      parsedParams = JSON.parse(contents)
    } catch (error: any) {
      trackEvent(
        AnalyticsEvent.MALFORMED_TOOL_CALL_JSON,
        loggerOptions?.userId ?? '',
        {
          contents: JSON.stringify(contents),
          model: loggerOptions?.model,
          agent: loggerOptions?.agentName,
          error: {
            name: error.name,
            message: error.message,
            stack: error.stack,
          },
          autocompleted,
        },
      )
      const shortenedContents =
        contents.length < 50
          ? contents
          : contents.slice(0, 20) + '...' + contents.slice(-20)
      const errorMessage = `Invalid JSON: ${JSON.stringify(shortenedContents)}\nError: ${error.message}`
      onResponseChunk({
        type: 'error',
        message: errorMessage,
      })
      onError('parse_error', errorMessage)
      return
    }

    const toolName = parsedParams[toolNameParam] as keyof typeof processors
    if (!processors[toolName]) {
      trackEvent(
        AnalyticsEvent.UNKNOWN_TOOL_CALL,
        loggerOptions?.userId ?? '',
        {
          contents,
          toolName,
          model: loggerOptions?.model,
          agent: loggerOptions?.agentName,
          autocompleted,
        },
      )
      onError(toolName, `Tool not found: ${toolName}`)
      return
    }

    trackEvent(AnalyticsEvent.TOOL_USE, loggerOptions?.userId ?? '', {
      toolName,
      contents,
      parsedParams,
      autocompleted,
      model: loggerOptions?.model,
      agent: loggerOptions?.agentName,
    })
    delete parsedParams[toolNameParam]

    processors[toolName].onTagStart(toolName, {})
    processors[toolName].onTagEnd(toolName, parsedParams)
  }

  function extractToolsFromBufferAndProcess() {
    const matches = extractToolCalls()
    matches.forEach(processToolCallContents)
  }

  function* processChunk(chunk: string | undefined) {
    if (chunk !== undefined) {
      buffer += chunk
    }
    extractToolsFromBufferAndProcess()

    if (chunk === undefined) {
      streamCompleted = true
      if (buffer.includes(startToolTag)) {
        buffer += completionSuffix
        chunk = completionSuffix
        autocompleted = true
      }
      extractToolsFromBufferAndProcess()
    }

    if (chunk) {
      yield chunk
    }
  }

  for await (const chunk of stream as AsyncIterable<string>) {
    if (streamCompleted) {
      break
    }
    yield* processChunk(chunk)
  }

  if (!streamCompleted) {
    // After the stream ends, try parsing one last time in case there's leftover text
    yield* processChunk(undefined)
  }

  for await (const chunk of stream as AsyncIterable<string>) {
  }
}

import { initialSessionState, type RunState } from './run-state'
import { changeFile } from './tools/change-file'
import { getFiles } from './tools/read-files'
import { runTerminalCommand } from './tools/run-terminal-command'
import { WebSocketHandler } from './websocket-client'
import {
  PromptResponseSchema,
  type ServerAction,
} from '../../common/src/actions'
import { API_KEY_ENV_VAR } from '../../common/src/constants'
import { DEFAULT_MAX_AGENT_STEPS } from '../../common/src/json-config/constants'

import type { AgentDefinition } from '../../common/src/templates/initial-agents-dir/types/agent-definition'
import type { PrintModeEvent } from '../../common/src/types/print-mode'

type ClientToolName = 'write_file' | 'run_terminal_command'

export type CodebuffClientOptions = {
  // Provide an API key or set the CODEBUFF_API_KEY environment variable.
  apiKey?: string
  cwd: string
  onError: (error: { message: string }) => void
  overrideTools?: Partial<
    Record<
      ClientToolName,
      (
        input: ServerAction<'tool-call-request'>['input'],
      ) => Promise<{ toolResultMessage: string }>
    > & {
      // Include read_files separately, since it has a different signature.
      read_files: (
        filePath: string[],
      ) => Promise<{ files: Record<string, string | null> }>
    }
  >
}

export class CodebuffClient {
  public cwd: string

  private readonly websocketHandler: WebSocketHandler
  private readonly overrideTools: NonNullable<
    CodebuffClientOptions['overrideTools']
  >
  private readonly fingerprintId = `codebuff-sdk-${Math.random().toString(36).substring(2, 15)}`

  private readonly promptIdToHandleEvent: Record<
    string,
    (event: PrintModeEvent) => void
  > = {}
  private readonly promptIdToResolveResponse: Record<
    string,
    { resolve: (response: any) => void; reject: (error: any) => void }
  > = {}

  constructor({ apiKey, cwd, onError, overrideTools }: CodebuffClientOptions) {
    const foundApiKey = apiKey ?? process.env[API_KEY_ENV_VAR]
    if (!foundApiKey) {
      throw new Error(
        `Codebuff API key not found. Please provide an apiKey in the constructor of CodebuffClient or set the ${API_KEY_ENV_VAR} environment variable.`,
      )
    }

    this.cwd = cwd
    this.overrideTools = overrideTools ?? {}
    this.websocketHandler = new WebSocketHandler({
      apiKey: foundApiKey,
      onWebsocketError: (error) => {
        onError({ message: error.message })
      },
      onWebsocketReconnect: () => {},
      onRequestReconnect: async () => {},
      onResponseError: async (error) => {
        onError({ message: error.message })
      },
      readFiles: this.readFiles.bind(this),
      handleToolCall: this.handleToolCall.bind(this),
      onCostResponse: async () => {},

      onResponseChunk: async (action) => {
        const { userInputId, chunk } = action
        const handleEvent = this.promptIdToHandleEvent[userInputId]
        if (handleEvent && typeof chunk === 'object') {
          handleEvent(chunk)
        }
      },
      onSubagentResponseChunk: async () => {},

      onPromptResponse: this.handlePromptResponse.bind(this),
    })
  }

  public closeConnection() {
    this.websocketHandler.close()
  }

  /**
   * Run a Codebuff agent with the specified options.
   *
   * @param agent - The agent to run. Use 'base' for the default agent, or specify a custom agent ID if you made your own agent config.
   * @param prompt - The user prompt describing what you want the agent to do.
   * @param params - (Optional) Additional parameters for the agent. Most agents don't use this, but some custom agents can take a JSON object as input in addition to the user prompt string.
   * @param handleEvent - (Optional) Callback function that receives every event during execution (assistant messages, tool calls, etc.). This allows you to stream the agent's progress in real-time. We will likely add a token-by-token streaming callback in the future.
   * @param previousRun - (Optional) JSON state returned from a previous run() call. Use this to continue a conversation or session with the agent, maintaining context from previous interactions.
   * @param projectFiles - (Optional) All the files in your project as a plain JavaScript object. Keys should be the full path from your current directory to each file, and values should be the string contents of the file. Example: { "src/index.ts": "console.log('hi')" }. This helps Codebuff pick good source files for context.
   * @param knowledgeFiles - (Optional) Knowledge files to inject into every run() call. Uses the same schema as projectFiles - keys are file paths and values are file contents. These files are added directly to the agent's context.
   * @param agentDefinitions - (Optional) Array of custom agent definitions. Each object should satisfy the AgentDefinition type. You can input the agent's id field into the agent parameter to run that agent.
   * @param maxAgentSteps - (Optional) Maximum number of steps the agent can take before stopping. Use this as a safety measure in case your agent starts going off the rails. A reasonable number is around 20.
   *
   * @returns A Promise that resolves to a RunState JSON object which you can pass to a subsequent run() call to continue the run.
   */
  public async run({
    agent,
    prompt,
    params,
    handleEvent,
    previousRun,
    projectFiles,
    knowledgeFiles,
    agentDefinitions,
    maxAgentSteps = DEFAULT_MAX_AGENT_STEPS,
  }: {
    agent: string
    prompt: string
    params?: Record<string, any>
    handleEvent?: (event: PrintModeEvent) => void
    previousRun?: RunState
    projectFiles?: Record<string, string>
    knowledgeFiles?: Record<string, string>
    agentDefinitions?: AgentDefinition[]
    maxAgentSteps?: number
  }): Promise<RunState> {
    await this.websocketHandler.connect()

    const promptId = Math.random().toString(36).substring(2, 15)
    const sessionState =
      previousRun?.sessionState ??
      initialSessionState(this.cwd, {
        knowledgeFiles,
        agentDefinitions,
        projectFiles,
        maxAgentSteps,
      })
    sessionState.mainAgentState.stepsRemaining = maxAgentSteps
    const toolResults = previousRun?.toolResults ?? []
    if (handleEvent) {
      this.promptIdToHandleEvent[promptId] = handleEvent
    }
    this.websocketHandler.sendInput({
      promptId,
      prompt,
      promptParams: params,
      fingerprintId: this.fingerprintId,
      costMode: 'normal',
      sessionState,
      toolResults,
      agentId: agent,
    })

    return new Promise<RunState>((resolve, reject) => {
      this.promptIdToResolveResponse[promptId] = { resolve, reject }
    })
  }

  private async handlePromptResponse(action: ServerAction<'prompt-response'>) {
    const promiseActions =
      this.promptIdToResolveResponse[action?.promptId ?? '']

    const parsedAction = PromptResponseSchema.safeParse(action)
    if (!parsedAction.success) {
      const message = [
        'Received invalid prompt response from server:',
        JSON.stringify(parsedAction.error.issues),
        'If this issues persists, please contact support@codebuff.com',
      ].join('\n')
      if (promiseActions) {
        promiseActions.reject(new Error(message))
      }
      return
    }

    if (promiseActions) {
      const { sessionState, toolResults } = parsedAction.data
      const state: RunState = {
        sessionState,
        toolResults,
      }
      promiseActions.resolve(state)

      delete this.promptIdToResolveResponse[action.promptId]
      delete this.promptIdToHandleEvent[action.promptId]
    }
  }

  private async readFiles(filePath: string[]) {
    const override = this.overrideTools.read_files
    if (override) {
      const overrideResult = await override(filePath)
      return overrideResult.files
    }
    return getFiles(filePath, this.cwd)
  }

  private async handleToolCall(
    action: ServerAction<'tool-call-request'>,
  ): ReturnType<WebSocketHandler['handleToolCall']> {
    const toolName = action.toolName
    const input = action.input
    let result: string
    try {
      let override = this.overrideTools[toolName as ClientToolName]
      if (!override && toolName === 'str_replace') {
        // Note: write_file and str_replace have the same implementation, so reuse their write_file override.
        override = this.overrideTools['write_file']
      }
      if (override) {
        const overrideResult = await override(input)
        result = overrideResult.toolResultMessage
      } else if (toolName === 'end_turn') {
        result = ''
      } else if (toolName === 'write_file' || toolName === 'str_replace') {
        const r = changeFile(input, this.cwd)
        result = r.toolResultMessage
      } else if (toolName === 'run_terminal_command') {
        const r = await runTerminalCommand({
          ...input,
          cwd: input.cwd ?? this.cwd,
        } as Parameters<typeof runTerminalCommand>[0])
        result = r.output
      } else {
        throw new Error(
          `Tool not implemented in SDK. Please provide an override or modify your agent to not use this tool: ${toolName}`,
        )
      }
    } catch (error) {
      return {
        success: false,
        output: {
          type: 'text',
          value:
            error &&
            typeof error === 'object' &&
            'message' in error &&
            typeof error.message === 'string'
              ? error.message
              : typeof error === 'string'
                ? error
                : 'Unknown error',
        },
      }
    }
    return {
      success: true,
      output: {
        type: 'text',
        value: result,
      },
    }
  }
}

import { WEBSOCKET_URL } from './constants'
import { APIRealtimeClient } from '../../common/src/websockets/websocket-client'

import type { ServerAction, ClientAction } from '../../common/src/actions'
import type { WebSocket } from 'ws'

export type WebSocketHandlerOptions = {
  onWebsocketError?: (error: WebSocket.ErrorEvent) => void
  onWebsocketReconnect?: () => void
  onRequestReconnect?: () => Promise<void>
  onResponseError?: (error: ServerAction<'action-error'>) => Promise<void>
  readFiles: (
    filePath: string[],
  ) => Promise<ClientAction<'read-files-response'>['files']>
  handleToolCall: (
    action: ServerAction<'tool-call-request'>,
  ) => Promise<Omit<ClientAction<'tool-call-response'>, 'type' | 'requestId'>>
  onCostResponse?: (
    action: ServerAction<'message-cost-response'>,
  ) => Promise<void>

  onResponseChunk?: (action: ServerAction<'response-chunk'>) => Promise<void>
  onSubagentResponseChunk?: (
    action: ServerAction<'subagent-response-chunk'>,
  ) => Promise<void>

  onPromptResponse?: (action: ServerAction<'prompt-response'>) => Promise<void>

  apiKey: string
}

type WebSocketHandlerOptionsWithDefaults = Required<WebSocketHandlerOptions>

export class WebSocketHandler {
  private cbWebSocket: APIRealtimeClient
  private onRequestReconnect: WebSocketHandlerOptionsWithDefaults['onRequestReconnect']

  private onResponseError: WebSocketHandlerOptionsWithDefaults['onResponseError']
  private readFiles: WebSocketHandlerOptionsWithDefaults['readFiles']
  private handleToolCall: WebSocketHandlerOptionsWithDefaults['handleToolCall']
  private onCostResponse: WebSocketHandlerOptionsWithDefaults['onCostResponse']
  private onResponseChunk: WebSocketHandlerOptionsWithDefaults['onResponseChunk']
  private onSubagentResponseChunk: WebSocketHandlerOptionsWithDefaults['onSubagentResponseChunk']
  private onPromptResponse: WebSocketHandlerOptionsWithDefaults['onPromptResponse']
  private apiKey: string
  private isConnected = false

  constructor({
    onWebsocketError = () => {},
    onWebsocketReconnect = () => {},
    onRequestReconnect = async () => {},
    onResponseError = async () => {},
    readFiles,
    handleToolCall,
    onCostResponse = async () => {},

    onResponseChunk = async () => {},
    onSubagentResponseChunk = async () => {},

    onPromptResponse = async () => {},

    apiKey,
  }: WebSocketHandlerOptions) {
    this.cbWebSocket = new APIRealtimeClient(
      WEBSOCKET_URL,
      onWebsocketError,
      onWebsocketReconnect,
    )
    this.onRequestReconnect = onRequestReconnect

    this.onResponseError = onResponseError
    this.readFiles = readFiles
    this.handleToolCall = handleToolCall
    this.onCostResponse = onCostResponse

    this.onResponseChunk = onResponseChunk
    this.onSubagentResponseChunk = onSubagentResponseChunk

    this.onPromptResponse = onPromptResponse

    this.apiKey = apiKey
  }

  public async connect() {
    if (!this.isConnected) {
      await this.cbWebSocket.connect()
      this.setupSubscriptions()
      this.isConnected = true
    }
  }

  public reconnect() {
    this.cbWebSocket.forceReconnect()
  }

  public close() {
    this.cbWebSocket.close()
  }

  private setupSubscriptions() {
    this.cbWebSocket.subscribe('action-error', this.onResponseError)

    this.cbWebSocket.subscribe('read-files', async (a) => {
      const { filePaths, requestId } = a
      const files = await this.readFiles(filePaths)

      this.cbWebSocket.sendAction({
        type: 'read-files-response',
        files,
        requestId,
      })
    })

    // Handle backend-initiated tool call requests
    this.cbWebSocket.subscribe('tool-call-request', async (action) => {
      const toolCallResult = await this.handleToolCall(action)

      this.cbWebSocket.sendAction({
        type: 'tool-call-response',
        requestId: action.requestId,
        ...toolCallResult,
      })
    })

    this.cbWebSocket.subscribe('message-cost-response', this.onCostResponse)

    // Used to handle server restarts gracefully
    this.cbWebSocket.subscribe('request-reconnect', this.onRequestReconnect)

    // Handle streaming messages
    this.cbWebSocket.subscribe('response-chunk', this.onResponseChunk)
    this.cbWebSocket.subscribe(
      'subagent-response-chunk',
      this.onSubagentResponseChunk,
    )

    // Handle full response from prompt
    this.cbWebSocket.subscribe('prompt-response', this.onPromptResponse)
  }

  private getInputDefaultOptions() {
    return {
      ...({
        type: 'prompt',
      } as const),
      authToken: this.apiKey,
    }
  }

  public sendInput(
    action: Omit<
      ClientAction<'prompt'>,
      keyof ReturnType<typeof this.getInputDefaultOptions>
    >,
  ) {
    this.cbWebSocket.sendAction({
      ...action,
      ...this.getInputDefaultOptions(),
    })
  }

  public cancelInput({ promptId }: { promptId: string }) {
    this.cbWebSocket.sendAction({
      type: 'cancel-user-input',
      authToken: this.apiKey,
      promptId,
    })
  }
}

