import type { z } from 'zod/v4'
import type { JSONSchema } from 'zod/v4/core'

export type CustomToolDefinition = {
  toolName: string
  description: string
  parameters: z.ZodType | JSONSchema.BaseSchema
  endsAgentStep?: boolean
}

export type CustomToolDefinitions = Record<string, CustomToolDefinition>

// Helper to create a custom tool definition with proper typing
export function defineCustomTool<T extends z.ZodType>(config: {
  toolName: string
  description: string
  parameters: T
  endsAgentStep?: boolean
}): CustomToolDefinition {
  return {
    toolName: config.toolName,
    description: config.description,
    parameters: config.parameters,
    endsAgentStep: config.endsAgentStep ?? true,
  }
}
