// Update to handle both built-in and custom tools
export type ToolDefinition<T extends string = string> = 
  T extends BuiltInToolName 
    ? (typeof toolDescriptions)[T] & (typeof llmToolCallSchema)[T]
    : CustomToolDefinition

// Helper to merge built-in and custom tool definitions
export function getToolDefinitions(
  customTools?: CustomToolDefinitions
): Record<string, ToolDefinition> {
  const builtInDefs = Object.fromEntries(
    Object.entries(toolDescriptions).map(([toolName, toolDescription]) => [
      toolName,
      {
        ...toolDescriptions[toolName as BuiltInToolName],
        ...llmToolCallSchema[toolName as BuiltInToolName],
      } satisfies ToolDefinition,
    ]),
  ) as { [K in BuiltInToolName]: ToolDefinition<K> }

  if (!customTools) {
    return builtInDefs
  }

  return {
    ...builtInDefs,
    ...customTools,
  }
}
