export async function processStreamWithTools<T extends string>(options: {
  stream: AsyncGenerator<T> | ReadableStream<T>
  // ... other params
  fileContext: ProjectFileContext
  // ... other params
}) {
  const { fileContext, agentTemplate } = options

  // Merge built-in and custom tool definitions
  const allToolDefs = getToolDefinitions(fileContext.customToolDefinitions)

  // Filter to only tools available to this agent
  const availableTools = Object.fromEntries(
    Object.entries(allToolDefs).filter(([toolName]) =>
      agentTemplate.toolNames.includes(toolName)
    )
  )

  function toolCallback(toolName: string) {
    return {
      onTagStart: () => {},
      onTagEnd: async (_: string, input: Record<string, string>) => {
        // Handle both built-in and custom tools
        previousToolCallFinished = executeToolCall({
          toolName,
          input,
          // ... other params
        })
      },
    }
  }

  const streamWithTags = processStreamWithTags(
    stream,
    Object.fromEntries(
      Object.keys(availableTools).map((toolName) => [toolName, toolCallback(toolName)])
    ),
    // ... rest of params
  )

  // ... rest of function
}
