import type { CustomToolDefinitions } from '@codebuff/common/tools/custom-tool-definition'

export function getAllToolDefinitions(
  customTools?: CustomToolDefinitions
): Record<string, any> {
  if (!customTools || Object.keys(customTools).length === 0) {
    return codebuffToolDefs
  }

  // Validate no name conflicts with built-in tools
  const conflicts = Object.keys(customTools).filter(name => name in codebuffToolDefs)
  if (conflicts.length > 0) {
    throw new Error(
      `Custom tool names conflict with built-in tools: ${conflicts.join(', ')}`
    )
  }

  return { ...codebuffToolDefs, ...customTools }
}
```

