```typescript
private async handleToolCall(action: ServerAction<'tool-call-request'>) {
  const toolName = action.toolName
  const input = action.input

  // 1. Check override first (works for custom tools + built-in overrides)
  const override = this.overrideTools[toolName]
  if (override) {
    const result = await override(input)
    return { 
      success: true, 
      output: { type: 'text', value: result.toolResultMessage } 
    }
  }

  // 2. Handle built-in client tools (existing logic unchanged)
  if (toolName === 'end_turn') {
    return { success: true, output: { type: 'text', value: '' } }
  }
  if (toolName === 'write_file' || toolName === 'str_replace') {
    const r = changeFile(input, this.cwd)
    return { success: true, output: { type: 'text', value: r.toolResultMessage } }
  }
  if (toolName === 'run_terminal_command') {
    const r = await runTerminalCommand({ ...input, cwd: input.cwd ?? this.cwd })
    return { success: true, output: { type: 'text', value: r.output } }
  }

  // 3. Unknown tool - likely custom tool without override
  throw new Error(
    `Tool '${toolName}' is not implemented. ` +
    `If this is a custom tool, provide a handler function in the 'overrideTools' parameter.`
  )
}
```

**Rationale:** Reuse existing override mechanism for custom tools - simplest approach with no new concepts. Error message clarifies that custom tools require overrides.

